// BCM update for one neuron (rates in Hz); call every time step
function bcmStep(w, x, y, s, p) {
  s.theta += (p.dt / p.tauTheta) * (y * y / p.y0 - s.theta);  // sliding threshold
  for (let i = 0; i < w.length; i++) {
    w[i] += p.eta * x[i] * y * (y - s.theta) * p.dt;
    w[i] = Math.max(0, w[i]);
  }
}
